<?php if(commerce_ready()): $foodReviewCount=(int)q('SELECT COUNT(*) FROM product_reviews WHERE seller_id=?',[$s['user_id']])->fetchColumn();$foodPages=max(1,(int)ceil($foodReviewCount/30));$foodPage=max(1,min($foodPages,(int)param('food_page')?:1));$foodReviews=all('SELECT r.*,u.full_name,m.id existing_product,m.status product_status FROM product_reviews r JOIN users u ON u.id=r.user_id LEFT JOIN menu_items m ON m.id=r.product_id WHERE r.seller_id=? ORDER BY r.updated_at DESC,r.id DESC LIMIT 30 OFFSET '.(($foodPage-1)*30),[$s['user_id']]); ?>
<section class="restaurant-reviews" id="food-reviews"><div class="page-heading"><span class="heading-kicker"><?=e(t('FROM COMPLETED ORDERS'))?></span><h2><?=e(t('Food Reviews'))?></h2><p><?=e(t('Reviews stay with this kitchen even when a dish is no longer offered.'))?></p></div><div class="review-list"><?php if(!$foodReviews): ?><div class="panel"><p><?=e(t('No food reviews yet.'))?></p></div><?php endif ?><?php foreach($foodReviews as $r): ?><article class="panel"><div class="review-person"><strong><?=e($r['full_name'])?></strong><small><?=e(local_time($r['updated_at'],'d M Y'))?></small></div><h3><?=e($r['product_name'])?></h3><div class="order-meta"><span class="chip"><?=e(t('Verified order'))?></span><?php if(!$r['existing_product']||$r['product_status']==='archived'): ?><span><?=e(t('No longer offered'))?></span><?php endif ?></div><?=rating_html((float)$r['rating'],1)?><p><?=nl2br(e($r['review_text']))?></p></article><?php endforeach ?></div><?php if($foodPages>1): ?><nav class="pagination" aria-label="<?=e(t('Food review pages'))?>"><?php if($foodPage>1): ?><a class="pill" href="<?=e(url('restaurant.php?id='.$s['id'].'&food_page='.($foodPage-1).'#food-reviews'))?>"><?=e(t('← Previous'))?></a><?php endif ?><span><?=e(t('Page'))?> <?=$foodPage?> <?=e(t('of'))?> <?=$foodPages?></span><?php if($foodPage<$foodPages): ?><a class="pill" href="<?=e(url('restaurant.php?id='.$s['id'].'&food_page='.($foodPage+1).'#food-reviews'))?>"><?=e(t('Next →'))?></a><?php endif ?></nav><?php endif ?></section><?php endif ?>
